// This file is generated by AI.

// 选项卡序列的纯函数。
//
// 抽出来的原因: 新增/关闭/重排的顺序规则容易被后续改动破坏, 而这些规则都是
// "给定序列与操作, 得出新序列与新的活动项"的纯逻辑, 适合单测覆盖。

import type { WorkbenchTabItem } from './model';

/** 记住最近激活的 tab id，保证历史不重复且最新项在末尾 */
export function rememberTabActivation(history: string[], id: string): string[] {
  if (!id) return history;
  const next = [...new Set(history.filter((item) => item !== id))];
  next.push(id);
  return next;
}

/** 返回最近使用顺序 (最近激活的在前), 并补齐尚未进入历史记录的选项卡 */
export function recentTabIds(tabs: WorkbenchTabItem[], history: string[]): string[] {
  const available = new Set(tabs.map((tab) => tab.id));
  const seen = new Set<string>();
  const recent: string[] = [];

  for (let index = history.length - 1; index >= 0; index -= 1) {
    const id = history[index];
    if (id && available.has(id) && !seen.has(id)) {
      recent.push(id);
      seen.add(id);
    }
  }

  for (const tab of tabs) {
    if (!seen.has(tab.id)) {
      recent.push(tab.id);
      seen.add(tab.id);
    }
  }

  return recent;
}

/** 在最近使用顺序中移动一项; direction 为 1 向较旧项移动, -1 向较新项移动 */
export function cycleRecentTab(ids: string[], currentId: string | null, direction: 1 | -1): string | null {
  if (ids.length === 0) return null;
  const currentIndex = currentId === null ? -1 : ids.indexOf(currentId);
  const nextIndex =
    currentIndex < 0 ? (direction === 1 ? 0 : ids.length - 1) : (currentIndex + direction + ids.length) % ids.length;
  return ids[nextIndex] ?? null;
}

/** 按类型和标题整理标签顺序 */
export function orderTabs(tabs: WorkbenchTabItem[]): WorkbenchTabItem[] {
  const kindRank: Record<WorkbenchTabItem['kind'], number> = {
    'voice-workbench': 0,
    scene: 1,
    config: 2,
    resource: 3,
    novel: 4,
    diff: 5,
    guidance: 6,
  };
  const resourceRank: Record<Extract<WorkbenchTabItem, { kind: 'resource' }>['resourceKind'], number> = {
    image: 0,
    audio: 1,
    video: 2,
    text: 3,
  };
  const diffRank: Record<Extract<WorkbenchTabItem, { kind: 'diff' }>['diffKind'], number> = {
    staged: 0,
    unstaged: 1,
    commit: 2,
  };

  return [...tabs].sort((left, right) => {
    const kindDelta = (kindRank[left.kind] ?? 99) - (kindRank[right.kind] ?? 99);
    if (kindDelta !== 0) return kindDelta;
    if (left.kind === 'scene' && right.kind === 'scene') {
      const leftIsStart = left.path.replace(/\\/g, '/').split('/').at(-1)?.toLowerCase() === 'start.txt';
      const rightIsStart = right.path.replace(/\\/g, '/').split('/').at(-1)?.toLowerCase() === 'start.txt';
      if (leftIsStart !== rightIsStart) return leftIsStart ? -1 : 1;
    }
    if (left.kind === 'resource' && right.kind === 'resource') {
      const resourceDelta = resourceRank[left.resourceKind] - resourceRank[right.resourceKind];
      if (resourceDelta !== 0) return resourceDelta;
    }
    if (left.kind === 'diff' && right.kind === 'diff') {
      const diffDelta = diffRank[left.diffKind] - diffRank[right.diffKind];
      if (diffDelta !== 0) return diffDelta;
    }
    return (left.title ?? '').localeCompare(right.title ?? '', undefined, { numeric: true, sensitivity: 'base' });
  });
}

/** 把新选项卡插到活动选项卡之后 (与其他编辑器一致); 无活动项则追加到末尾 */
export function insertTab(
  tabs: WorkbenchTabItem[],
  tab: WorkbenchTabItem,
  activeId: string | null
): {
  tabs: WorkbenchTabItem[];
  activeId: string;
} {
  const existing = tabs.findIndex((item) => item.id === tab.id);
  if (existing >= 0) {
    // 已存在: 只更新内容并激活, 不改变位置
    const next = [...tabs];
    next[existing] = tab;
    return { tabs: next, activeId: tab.id };
  }
  if (activeId === null) {
    return { tabs: [...tabs, tab], activeId: tab.id };
  }
  const at = tabs.findIndex((item) => item.id === activeId);
  if (at < 0) {
    return { tabs: [...tabs, tab], activeId: tab.id };
  }
  const next = [...tabs];
  next.splice(at + 1, 0, tab);
  return { tabs: next, activeId: tab.id };
}

/**
 * 关闭选项卡。
 *
 * 关闭活动项时优先激活最近使用的仍打开项; 没有历史记录时回退到相邻项。
 */
export function closeTab(
  tabs: WorkbenchTabItem[],
  id: string,
  activeId: string | null,
  history: string[] = []
): { tabs: WorkbenchTabItem[]; activeId: string | null } {
  const at = tabs.findIndex((item) => item.id === id);
  if (at < 0) return { tabs, activeId };
  const next = tabs.filter((item) => item.id !== id);
  if (activeId !== id) return { tabs: next, activeId };
  if (next.length === 0) return { tabs: next, activeId: null };
  const recentId = [...history].reverse().find((tabId) => tabId !== id && next.some((tab) => tab.id === tabId));
  const fallback = next.find((tab) => tab.id === recentId) ?? next[Math.min(at, next.length - 1)];
  return { tabs: next, activeId: fallback.id };
}

/**
 * 把 `id` 移动到 `toIndex` 位置。
 *
 * 与场景浏览器等处的语义一致: `toIndex` 是**目标槽位**, 而非"插入到第几项之前"。
 */
export function moveTab(tabs: WorkbenchTabItem[], id: string, toIndex: number): WorkbenchTabItem[] {
  const from = tabs.findIndex((item) => item.id === id);
  if (from < 0) return tabs;
  const clamped = Math.max(0, Math.min(toIndex, tabs.length - 1));
  if (from === clamped) return tabs;
  const next = [...tabs];
  const [tab] = next.splice(from, 1);
  next.splice(clamped, 0, tab);
  return next;
}

/** 关闭某一类选项卡 (退出项目时清理) */
export function removeTabsByKind(tabs: WorkbenchTabItem[], kind: WorkbenchTabItem['kind']): WorkbenchTabItem[] {
  return tabs.filter((tab) => tab.kind !== kind);
}
